<template><div><h1 class="mb-6 text-2xl font-bold">회원 관리</h1><div class="rounded bg-white shadow"><div v-for="m in page?.content" :key="m.id" class="flex items-center justify-between border-b p-4"><div>{{m.userid}} / {{m.name}} / {{m.role}}</div><div class="flex gap-2"><button @click="toggle(m.id)" class="rounded border px-3 py-1">{{m.enabled?'비활성':'활성'}}</button><button @click="del(m.id)" class="rounded border px-3 py-1 text-red-600">삭제</button></div></div></div><Pagination :page="page" @change="load"/></div></template>
<script setup>import{onMounted,ref}from'vue';import{adminApi}from'../../api/adminApi';import Pagination from'../../components/Pagination.vue';const page=ref(null);async function load(p=0){page.value=(await adminApi.members({page:p,size:10})).data}async function toggle(id){await adminApi.toggleMember(id);await load(page.value.number)}async function del(id){if(confirm('삭제할까요?')){await adminApi.deleteMember(id);await load(page.value.number)}}onMounted(load)</script>